    hop() { const a = A(); if (!a) return; const t = a.c.currentTime; tone(a, t, "sine", 620, 420, 0.22, 0.001, 0.06); noise(a, t, "bandpass", 1900, 1200, 2, 0.12, 0.001, 0.03); },
    brake() { const a = A(); if (!a) return; const t = a.c.currentTime; noise(a, t, "bandpass", 3400, 900, 0.7, 0.62, 0.02, 1.3); tone(a, t, "sawtooth", 180, 52, 0.16, 0.02, 1.2, null, 900); },
    throw_() { const a = A(); if (!a) return; const t = a.c.currentTime; noise(a, t, "bandpass", 600, 3000, 1.4, 0.6, 0.1, 0.34); tone(a, t, "sine", 1100, 2200, 0.08, 0.05, 0.6); },
    tick() { const a = A(); if (!a) return; const t = a.c.currentTime; tone(a, t, "sine", 3300, 3100, 0.34, 0.001, 0.09); tone(a, t, "triangle", 1650, 1500, 0.1, 0.001, 0.07); },
    rumble(d) { const a = A(); if (!a) return; const t = a.c.currentTime; noise(a, t, "lowpass", 60, 460, 0.9, 1, d * 0.85, d); tone(a, t, "sawtooth", 28, 66, 0.5, d * 0.6, d, null, 240); tone(a, t + d * 0.5, "sine", 240, 3600, 0.12, d * 0.45, d * 0.5); for (let i = 0; i < 40; i++) { const q = Math.pow(Math.random(), 0.6) * d; noise(a, t + q, "bandpass", rnd(320, 1600), 200, 1.4, 0.16 * (q / d) + 0.04, 0.002, 0.08); } },
    explode() { const a = A(); if (!a) return; const t = a.c.currentTime; tone(a, t, "sine", 80, 20, 1, 0.002, 2.6); noise(a, t, "lowpass", 5200, 50, 0.7, 1, 0.002, 3.4); noise(a, t + 0.03, "bandpass", 1500, 120, 0.8, 1, 0.003, 2.2); tone(a, t, "sawtooth", 62, 18, 0.5, 0.002, 2.2, null, 420); for (let i = 0; i < 70; i++) { const q = Math.pow(Math.random(), 1.7) * 2.4; noise(a, t + q, "bandpass", rnd(200, 1700), 120, 1.2, rnd(0.1, 0.32) * (1 - q / 3), 0.002, rnd(0.04, 0.14)); } },
